import { useState } from 'react'
import { Checkbox } from 'moru-ui'

export function EmailPreference() {
  const [enabled, setEnabled] = useState(true)
  return (
    <Checkbox
      name="emailUpdates"
      checked={enabled}
      onCheckedChange={setEnabled}
      label="Email updates"
      description="Receive project news by email."
    />
  )
}
